function go(path){ history.pushState({},'',path); window.dispatchEvent(new Event('routechange')); window.scrollTo({top:0,behavior:'smooth'}); }
function Link({to, children, className=''}){ return <a href={to} className={className} onClick={e=>{if(!e.metaKey&&!e.ctrlKey){e.preventDefault();go(to)}}}>{children}</a> }

function Header(){
 const [open,setOpen]=useState(false); const [path,setPath]=useState(location.pathname);
 useEffect(()=>{const f=()=>{setPath(location.pathname);setOpen(false)}; addEventListener('popstate',f);addEventListener('routechange',f);return()=>{removeEventListener('popstate',f);removeEventListener('routechange',f)}},[]);
 const nav=[['/','Home'],['/courses','Courses'],['/about-us','About'],['/faculty','Faculty'],['/blog','Insights'],['/become-instructor','Teach']];
 return <><div className="topbar"><div className="container top-inner"><span><Phone size={14}/> +92 319 730 1071</span><span className="top-right"><Mail size={14}/> tarbiyahonline@meemacademy.org <i></i> Lahore, Pakistan <i></i><Link to="/login">Student login</Link></span></div></div>
 <header><div className="container nav"><Link to="/" className="brand"><img src={logo}/><span><b>MEEM</b><small>ACADEMIA</small></span></Link><nav className={open?'open':''}>{nav.map(([p,n])=><Link key={p} to={p} className={(path===p || p!=='/'&&path.startsWith(p))?'active':''}>{n}</Link>)}<Link to="/contact-us" className="nav-cta">Contact us <ArrowRight size={16}/></Link></nav><button className="menu" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></div></header></>
}

